            out.viol = ds.last.viol;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var rows = {};
            var j, g;
            for (j = 0; j < this.KEYS.length; j++) {
                g = this.KEYS[j];
                a[g] = this._active(dec, k, g);
                rows[g] = this.TABLE[g][a[g]];
            }
            var s0 = 0, s2 = 0, s3 = 0, s4 = 0, s5 = 0, rsum = 0;
            for (j = 0; j < this.KEYS.length; j++) {
                g = this.KEYS[j];
                s0 = s0 + rows[g][0];
                s2 = s2 + rows[g][2];
                s3 = s3 + rows[g][3];
                s4 = s4 + rows[g][4];
                s5 = s5 + rows[g][5];
                if (g !== this.MULT) { rsum = rsum + rows[g][1]; }
            }
            var rel = this._clamp(c.REL0 + s0, 0.0, c.STOPS);
            var exp = Math.max(0.0, c.EXP0 * rows[this.MULT][1] + rsum);
            var esc = Math.max(c.ESC_MIN, c.ESC0 + s2);
            var hrs = s4;
            var good = rel * (1.0 - esc / 100.0);
            var margin = c.MARGIN0 + c.REV_STOP * good + s3 - c.HR_RATE * hrs;
            var trust = this._clamp(c.TRUST0 + s5 - c.ESC_TRUST * esc, 0.0, 100.0);
            var breaches = 0;
            for (j = 0; j < this.KEYS.length; j++) {
                g = this.KEYS[j];
                if (this.ROUND_OF[g] <= k && this.HARD[g] === a[g]) { breaches += 1; }
            }
            return { k: k, a: a, rel: rel, good: good, exp: exp, esc: esc, hrs: hrs, margin: margin, trust: trust,
                     breaches: breaches, hard: breaches };
        }

        _components(r) {
            var c = this.C;
            var sc = this._clamp((r.good - c.S_LO) / (c.S_HI - c.S_LO), 0, 1);
            var rc = this._clamp((c.R_HI - r.exp) / c.R_HI, 0, 1);
            var bc = this._clamp((c.B_HI - r.esc) / c.B_HI, 0, 1);
            var mc = this._clamp((r.margin - c.M_LO) / (c.M_HI - c.M_LO), 0, 1);
            var tc = this._clamp((r.trust - c.T_LO) / (c.T_HI - c.T_LO), 0, 1);
            return [sc, rc, bc, mc, tc];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_S, c.W_R, c.W_B, c.W_M, c.W_T];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = ',' + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + '.' + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = Math.round(n * 100);
            var a = Math.abs(v);
            var whole = Math.floor(a / 100);
            var dec = a - whole * 100;
            return (v < 0 ? '-' : '') + String(whole) + '.' + (dec < 10 ? '0' : '') + String(dec);
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + '%';
        }

        _fmtPct(n) {
            return this._fmtInt(n) + '%';
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            return (v < 0 ? '-' : '') + '$' + this._fmtInt(Math.abs(v));
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var fH = ds.goodHistory || [];
            var rH = ds.expHistory || [];
            var bH = ds.escHistory || [];
            var mH = ds.marginHistory || [];
            var tH = ds.trustHistory || [];
            var vH = ds.violHistory || [];
            var n = fH.length;
            this._set('goodDisplay', n ? this._fmtDec2(fH[n - 1]) : '-');
            this._set('expDisplay', n ? this._fmtDec(rH[n - 1]) + ' ' + this._t('txt_unit') : '-');
            this._set('escDisplay', n ? this._fmtPct(bH[n - 1]) : '-');
            this._set('marginDisplay', n ? this._fmtMoney(mH[n - 1]) : '-');
            this._set('trustDisplay', n ? this._fmtDec(tH[n - 1]) : '-');
            this._set('violDisplay', n ? this._fmtInt(vH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var maps = {
                model1: { rent: 'fb_mo_rent', comm: 'fb_mo_comm', fake: 'fb_mo_fake', friends: 'fb_mo_friends' },
                price1: { cost: 'fb_pr_cost', low: 'fb_pr_low', high: 'fb_pr_high', quote: 'fb_pr_quote' },
                book2: { deposit: 'fb_bk_deposit', double: 'fb_bk_double', walkin: 'fb_bk_walkin', text: 'fb_bk_text' },
                staff2: { licensed: 'fb_st_licensed', unlic: 'fb_st_unlic', self: 'fb_st_self', turn: 'fb_st_turn' },
                san3: { full: 'fb_sa_full', endday: 'fb_sa_endday', spray: 'fb_sa_spray', deep: 'fb_sa_deep' },
                late3: { policy: 'fb_la_policy', waive: 'fb_la_waive', squeeze: 'fb_la_squeeze', ban: 'fb_la_ban' },
                tax4: { setaside: 'fb_tx_setaside', spend: 'fb_tx_spend', mix: 'fb_tx_mix', cpa: 'fb_tx_cpa' },
                grow4: { raise: 'fb_gr_raise', expand: 'fb_gr_expand', retail: 'fb_gr_retail', same: 'fb_gr_same' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

